#include <vector>
#include <string>
#include <cmath>
#include <algorithm>
#include <climits>

class Solution {
    long long nearestPal(long long x) {
        std::string s = std::to_string(x);
        int n = s.size();
        std::vector<long long> cands;
        cands.push_back((long long)std::pow(10, n - 1) - 1);
        cands.push_back((long long)std::pow(10, n) + 1);

        long long prefix = std::stoll(s.substr(0, (n + 1) / 2));
        for (long long diff = -1; diff <= 1; ++diff) {
            std::string p = std::to_string(prefix + diff);
            std::string rev = p;
            std::reverse(rev.begin(), rev.end());
            if (n % 2 == 0) {
                cands.push_back(std::stoll(p + rev));
            } else {
                cands.push_back(std::stoll(p + rev.substr(1)));
            }
        }

        long long best = cands[0];
        long long minDiff = std::abs(cands[0] - x);
        for (long long c : cands) {
            long long d = std::abs(c - x);
            if (d < minDiff) {
                minDiff = d;
                best = c;
            }
        }
        return best;
    }
public:
    long long minOperationsToPalindromic(std::vector<int>& nums) {
        long long total = 0;
        for (int x : nums) {
            total += std::abs(x - nearestPal(x));
        }
        return total;
    }
};

import java.util.*;

class Solution {
    private long nearestPal(long x) {
        String s = String.valueOf(x);
        int n = s.length();
        List<Long> cands = new ArrayList<>();
        cands.add((long) Math.pow(10, n - 1) - 1);
        cands.add((long) Math.pow(10, n) + 1);

        long prefix = Long.parseLong(s.substring(0, (n + 1) / 2));
        for (long diff = -1; diff <= 1; diff++) {
            String p = String.valueOf(prefix + diff);
            String rev = new StringBuilder(p).reverse().toString();
            if (n % 2 == 0) {
                cands.add(Long.parseLong(p + rev));
            } else {
                cands.add(Long.parseLong(p + rev.substring(1)));
            }
        }

        long best = cands.get(0);
        long minDiff = Math.abs(cands.get(0) - x);
        for (long c : cands) {
            long d = Math.abs(c - x);
            if (d < minDiff) {
                minDiff = d;
                best = c;
            }
        }
        return best;
    }

    public long minOperationsToPalindromic(int[] nums) {
        long total = 0;
        for (int x : nums) {
            total += Math.abs(x - nearestPal(x));
        }
        return total;
    }
}

function nearestPalindrome(x) {
    const s = String(x);
    const n = s.length;
    const candidates = [
        Math.pow(10, n - 1) - 1,
        Math.pow(10, n) + 1
    ];
    const prefix = parseInt(s.slice(0, Math.floor((n + 1) / 2)), 10);
    for (let diff = -1; diff <= 1; diff++) {
        const p = String(prefix + diff);
        const rev = p.split('').reverse().join('');
        if (n % 2 === 0) {
            candidates.push(parseInt(p + rev, 10));
        } else {
            candidates.push(parseInt(p + rev.slice(1), 10));
        }
    }

    let best = candidates[0];
    let minDiff = Math.abs(candidates[0] - x);
    for (const c of candidates) {
        const d = Math.abs(c - x);
        if (d < minDiff) {
            minDiff = d;
            best = c;
        }
    }
    return best;
}

